if (!defined('DIR_CORE')) {
    header('Location: static_pages/');
}

/**
 * This class is managing encryption/decryption of data in AbanteCart database tables
 * configured in $this->enc_data array
 * These tables need to have a specific postfix in the name like '_enc'
 *
 * Configuration:
 * Add the below configs to the /system / config.php file.
 * define('DATA_ENCRYPTION_ENABLED', true);
 * define('ENCRYPTED_POSTFIX', '_enc');
 * define('DATA_ENCRYPTION_KEYPAIR', 'data_enc_key');
 *
 * NOTE: DATA_ENCRYPTION_KEYPAIR is a default key, and it needs to be a files' name portion for public and private keys stored in ENCRYPTION_KEYS_DIR
 * Keys can be generated by ASSLEncryption class (see ASSLEncryption class) or by any other OpenSSL script
 * Example of keys: data_enc_key for data_enc_key.pub and data_enc_key.prv
 * This is also generated in encryption_data_manager extension
 *
 * Tables SQL:
 * New tables need to be created with provided SQL.
 * Encryption Data Manager extension runs SQL on installation
 *
 * Limitation: passphrase is not supported by data encryption.
 **/

final class ADataEncryption
{
    /** @var Registry|null */
    private $registry;
    /** @var ALog */
    private $log;
    /** @var AMessage */
    private $message;
    private $key_name;
    private $keys;
    private $passphrase;
    private $enc_data;
    private $postfix = '';
    public $active = false;

    function __construct(?string $keyName = null, ?string $passphrase = null)
    {
        //if not enabled exit
        if (!defined('DATA_ENCRYPTION_ENABLED') || !DATA_ENCRYPTION_ENABLED) {
            return null;
        }
        $this->registry = Registry::getInstance();
        $this->log = $this->registry->get('log');
        $this->message = $this->registry->get('messages');

        //load default key.
        //If the default key is not configured, key_name stays null,
        //and the error is reported on encryption/decryption (see detectEncryptKey/detectDecryptKey)
        if ($keyName) {
            $this->key_name = $keyName;
        } elseif (defined('DATA_ENCRYPTION_KEYPAIR')) {
            $this->key_name = (string)constant('DATA_ENCRYPTION_KEYPAIR');
        }
        if ($passphrase) {
            $this->passphrase = $passphrase;
        }

        //load keys from a database
        $this->loadKeys();

        //set tables/fields encrypted
        $this->enc_data['orders'] = [
            'id'     => 'order_id',
            'fields' => [
                'telephone',
                'fax',
                'email',
                'shipping_company',
                'shipping_address_1',
                'shipping_address_2',
                'shipping_city',
                'shipping_postcode',
                'shipping_country',
                'payment_company',
                'payment_address_1',
                'payment_address_2',
                'payment_city',
                'payment_postcode',
                'payment_country',
            ],
        ];
        $this->enc_data['customers'] = [
            'id'     => 'customer_id',
            'fields' => [
                'telephone',
                'fax',
                'email',
            ],
        ];
        $this->enc_data['addresses'] = [
            'id'     => 'address_id',
            'fields' => [
                'company',
                'address_1',
                'address_2',
                'postcode',
                'city',
            ],
        ];

        if (defined('ENCRYPTED_POSTFIX')) {
            $this->postfix = ENCRYPTED_POSTFIX;
        } else {
            $this->postfix = '_enc';
        }

        $this->active = true;
    }

    /**
     * @return array
     */
    public function getKeys()
    {
        return $this->keys;
    }

    /**
     * Get postfix used to extend tables storing encrypted data
     * This is only for tables that require encryption
     * This is set in ENCRYPTED_POSTFIX configuration
     *
     * @param string $table
     *
     * @return string
     */
    public function postfix($table)
    {
        //check if the table requires encryption and there is a postfix
        if ($this->getEncryptedTableID($table)) {
            return $this->postfix;
        } else {
            return '';
        }
    }

    /**
     * Get a list of tables containing encrypted data
     *
     * @return array
     */
    public function getEncryptedTables()
    {
        if (has_value($this->enc_data)) {
            return array_keys($this->enc_data);
        }
        return [];
    }

    /**
     * Get ID field name for table containing encrypted data
     *
     * @param string $table
     *
     * @return string
     */
    public function getEncryptedTableID(string $table)
    {
        if (has_value($this->enc_data) && isset($this->enc_data[$table])) {
            return $this->enc_data[$table]['id'];
        }
        return '';
    }

    /**
     * Get a list of encrypted fields in a table containing encrypted data
     *
     * @param string $table
     *
     * @return array
     */
    public function getEncryptedFields(string $table)
    {
        if (has_value($this->enc_data)) {
            return (array)($this->enc_data[$table]['fields'] ?? []);
        }
        return [];
    }

    /**
     * Add to the list of encrypted tables/fields containing encrypted data
     *
     * @param array $table_data
     *
     * @return null
     */
    public function addEncryptedTables(array $table_data)
    {
        foreach ($table_data as $table => $data) {
            if (in_array($table, $this->getEncryptedTables())) {
                $error = "ADataEncryption Error: Can't add existing table " . $table . "! Table already Exists";
                $this->log->write($error);
            } else {
                $this->enc_data[$table] = $data;
            }
        }
        return null;
    }

    /**
     * Add to the list of fields to existing tables containing encrypted data
     *
     * @param string $table
     * @param array $fields
     *
     * @return void
     *
     */
    public function addEncryptedFields(string $table, array $fields)
    {
        if (empty($table) || empty($fields)) {
            return;
        }

        foreach ($fields as $field) {
            if (!in_array($field, $this->getEncryptedFields($table))) {
                $this->enc_data[$table]['fields'][] = $field;
            }
        }
    }

    /**
     * Decrypt 1 row of data in a table for fields that are encrypted
     *
     * @param array $encryptedData
     * @param string $table
     * @param null|string $pass
     *
     * @return array
     * @throws AException
     */
    public function decrypt_data(array $encryptedData, string $table, ?string $pass = null)
    {
        if (empty($pass)) {
            $pass = $this->passphrase;
        }
        if (empty($table)) {
            return [];
        }
        //if encryption off returns pure data
        if (!$this->active) {
            return $encryptedData;
        }

        //detect key to use
        $keyName = $this->detectDecryptKey((int)($encryptedData['key_id'] ?? 0));

        $output = $encryptedData;
        $enc = new ASSLEncryption('', $keyName, $pass);
        $fields = $this->getEncryptedFields($table);
        foreach ($encryptedData as $key => $data) {
            if (in_array($key, $fields)) {
                $output[$key] = $enc->decrypt($data);
            }
        }
        return $output;
    }

    /**
     * Encrypt 1 row of data in the table for fields that are encrypted
     *
     * @param array $inData
     * @param string $table
     *
     * @return array
     * @throws AException
     */
    public function encrypt_data(array $inData, string $table)
    {
        if (empty($table)) {
            return [];
        }
        //if encryption off returns pure data
        if (!$this->active) {
            return $inData;
        }

        $key_name = $this->detectEncryptKey((int)($inData['key_id'] ?? 0));
        $inData['key_id'] = $this->getKeyIdByName($key_name);

        $output = $inData;
        $enc = new ASSLEncryption($key_name);
        $fields = $this->getEncryptedFields($table);
        foreach ($inData as $key => $data) {
            if (in_array($key, $fields)) {
                $output[$key] = $enc->encrypt($data);
            }
        }
        return $output;
    }

    /**
     * Encrypt 1 field of data
     *
     * @param string $value
     * @param int $keyId
     *
     * @return string
     * @throws AException
     */
    public function encrypt_field($value, int $keyId = 0)
    {
        //if encryption off returns pure data
        if (!$this->active) {
            return $value;
        }

        //detect key to use
        $key_name = $this->detectEncryptKey($keyId);
        $enc = new ASSLEncryption($key_name);
        return $enc->encrypt($value);
    }

    /**
     * Decrypt 1 field of data
     *
     * @param string $encryptedValue
     * @param int $keyId
     * @param null|string $pass
     *
     * @return string
     * @throws AException
     */
    public function decrypt_field($encryptedValue, int $keyId = 0, ?string $pass = null)
    {
        if (empty($pass)) {
            $pass = $this->passphrase;
        }
        //if encryption off returns pure data
        if (!$this->active) {
            return $encryptedValue;
        }

        //detect key to use
        $privateKeyName = $this->detectDecryptKey($keyId);

        $enc = new ASSLEncryption('', $privateKeyName, $pass);
        return $enc->decrypt($encryptedValue);
    }

    private function loadKeys()
    {
        $config = $this->registry->get('config');
        $cache = $this->registry->get('cache');
        $cacheKey = 'encryption.keys.store_' . (int)$config->get('config_store_id');
        $this->keys = $cache->pull($cacheKey);
        if ($this->keys === false) {
            $this->keys = [];
            $db = $this->registry->get('db');
            $query = $db->query("SELECT * FROM " . $db->table('encryption_keys') . " WHERE status = 1");
            if (!$query->num_rows) {
                return;
            }
            foreach ($query->rows as $row) {
                $this->keys[(int)$row['key_id']] = $row['key_name'];
            }
            $cache->push($cacheKey, $this->keys);
        }
    }

    /**
     * @param int $keyId
     *
     * @return string
     * @throws AException
     */
    private function detectEncryptKey(int $keyId)
    {
        //detect a key to use (set default first)
        $keyName = $this->key_name;
        if ($keyId > 0) {
            //we have a specific key set for record
            if ($this->keys[$keyId]) {
                $keyName = $this->keys[$keyId];
            } else {
                //something happens. we don't have a key. Report incident.
                $error = "Error: Can not locate key ID: " . $keyId
                    . " in the encryption_keys table. Attempt to locate default keys! ";
                $this->log->write($error);
                $this->message->saveError('Data decryption error', $error);
                throw new AException (AC_ERR_LOAD, $error);
            }
        }

        if (!$keyName) {
            $error = "Error: Can not locate default key in configuration file. "
                . "Refer to data encryption configuration help!";
            $this->log->write($error);
            $this->message->saveError('Data encryption error', $error);
            throw new AException (AC_ERR_LOAD, $error);
        }

        return $keyName;
    }

    /**
     * @param int $keyId
     *
     * @return null|string
     * @throws AException
     */
    private function detectDecryptKey(int $keyId = 0)
    {
        $keyName = $this->key_name;
        if ($keyId > 0) {
            //we have a key set for record
            if ($this->keys[$keyId]) {
                $keyName = $this->keys[$keyId];
            } else {
                //something happens. we don't have a key. Report incident.
                $error = "Error: Can not locate key ID: " . $keyId 
                    . " in the encryption_keys table. Record data might not be decrypted! ";
                $this->log->write($error);
                $this->message->saveError('Data decryption error', $error);
                throw new AException (AC_ERR_LOAD, $error);
            }
        }

        if (!$keyName) {
            $error = "Error: Can not locate default key in configuration file. "
                . "Refer to data encryption configuration help!";
            $this->log->write($error);
            $this->message->saveError('Data decryption error', $error);
        }

        return $keyName;
    }

    /**
     * @param string $keyName
     *
     * @return int
     */
    private function getKeyIdByName(string $keyName)
    {
        if (!count($this->keys)) {
            return 0;
        }
        foreach ($this->keys as $id => $name) {
            if ($keyName == $name) {
                return $id;
            }
        }
        return 0;
    }
    
    // DEPRECATED METHODS
    // Todo: Remove them in the next minor release!
    /**
     * @deprecated 
     * @return array
     */
    public function getEcryptedTables()
    {
        return $this->getEncryptedTables();
    }
    /**
     * @param $table
     * @return string
     * @deprecated
     */
    public function getEcryptedTableID($table)
    {
        return $this->getEncryptedTableID($table);
    }

    /**
     * @param $table
     * @return array
     * @deprecated
     */
    public function getEcryptedFields($table)
    {
        return $this->getEncryptedFields($table);
    }

    /**
     * @param $table_data
     * @return null
     * @deprecated
     */
    public function addEcryptedTables($table_data)
    {
        return $this->addEncryptedTables($table_data);
    }
}
